  ('behind-the-glass', 'Behind the Glass', 'show', 2026, 'TV-MA', 2, null, array['Mystery', 'Thriller']::text[], array['Dark', 'Suspenseful', 'Mystery']::text[], 'A forensic glass restorer finds handprints inside a sealed museum case — prints that match her missing sister.', array['Mara Quinn', 'Theo Adeyemi', 'Lena Voss']::text[], 'Ines Valero', 'Tom Ashby', 98, true, null, 'https://images.unsplash.com/photo-1778585040075-0991abfd4ed9?auto=format&fit=crop&w=800&q=85', 'none'),
