  ('the-signal', 'The Signal', 'movie', 2025, 'PG-13', null, '2h 4m', array['Sci-Fi', 'Thriller']::text[], array['Cerebral', 'Atmospheric']::text[], 'A radio astronomer intercepts a transmission that seems to be coming from her own future.', array['Noor Haddad', 'Felix Grant']::text[], 'Dara Whitfield', 'Ben Osei', 93, true, 2, 'https://images.unsplash.com/photo-1614201842267-206a09286c3b?auto=format&fit=crop&w=500&q=80', 'none'),
  ('the-veil', 'The Veil', 'show', 2023, 'TV-MA', 1, null, array['Horror', 'Drama']::text[], array['Haunting', 'Intimate']::text[], 'A widow moves into a lake house where the fog carries voices from the families who lived there before.', array['Adele Park', 'Simon Reyes']::text[], 'Sofia Lindgren', 'Sofia Lindgren', 89, false, 3, 'https://images.unsplash.com/photo-1778585040075-0991abfd4ed9?auto=format&fit=crop&w=800&q=85', 'sepia(.9) hue-rotate(160deg) saturate(1.8)'),
  ('cold-open', 'Cold Open', 'movie', 2026, 'PG-13', null, '1h 38m', array['Comedy', 'Drama']::text[], array['Witty', 'Warm']::text[], 'A washed-up sketch writer gets one last week to save a late-night show nobody watches.', array['Gus Lindqvist', 'Tamsin Oyelaran']::text[], 'Jules Carver', 'Nina Patel', 84, true, null, 'https://images.unsplash.com/photo-1733232073397-80fb13ef3212?auto=format&fit=crop&w=500&q=80', 'sepia(.8) hue-rotate(-20deg)'),
  ('static-hearts', 'Static Hearts', 'show', 2026, 'TV-14', 1, null, array['Romance', 'Sci-Fi']::text[], array['Romantic', 'Offbeat']::text[], 'Two strangers keep hearing each other through a broken baby monitor — across two different decades.', array['June Alvarez', 'Kit Moreau']::text[], 'Ama Mensah', 'Coby Reyes', 80, true, null, 'https://images.unsplash.com/photo-1614201842267-206a09286c3b?auto=format&fit=crop&w=500&q=80', 'hue-rotate(250deg) saturate(1.6)'),
  ('dead-reckoning', 'Dead Reckoning', 'movie', 2022, 'R', null, '2h 11m', array['Action', 'Thriller']::text[], array['Relentless', 'Gritty']::text[], 'A disgraced navigator has one night to sail a stolen cargo ship through a storm and out of the cartel’s reach.', array['Owen Strand', 'Bea Kaminski']::text[], 'Viktor Hale', 'Ray Donnelly', 87, false, 4, 'https://images.unsplash.com/photo-1634840150834-f6d4544f5b9b?auto=format&fit=crop&w=500&q=80', 'hue-rotate(320deg) saturate(1.8)'),
